const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parses the build graph text format described in the task prompt.
 *
 * Returns `{ tasks, deps }` where `tasks` maps a task name to its cost and
 * `deps` maps a task name to the `Set` of names it depends on. Every name
 * that appears anywhere (as a task or as either side of a `dep` line) is
 * guaranteed to be a key of `deps`, even when it has no dependencies.
 *
 * Throws a `CliError` (exit code 2) for a malformed line or for a `dep`
 * line naming a task nothing ever declares.
 */
export function parseGraph(input) {
  const rawLines = input.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const tasks = new Map()
  const deps = new Map()
  const depUses = []

  const ensureDeps = (name) => {
    if (!deps.has(name)) deps.set(name, new Set())
  }

  for (let i = 0; i < rawLines.length; i++) {
    const lineNo = i + 1
    const line = rawLines[i].trim()
    if (line === '' || line.startsWith('#')) continue

    const tokens = line.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'task') {
      if (tokens.length !== 3) {
        throw new CliError(`error: line ${lineNo}: expected task <name> <cost>`)
      }
      const [, name, costStr] = tokens
      if (!NAME_RE.test(name)) {
        throw new CliError(`error: line ${lineNo}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(`error: line ${lineNo}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new CliError(`error: line ${lineNo}: task ${name} is declared twice`)
      }
      tasks.set(name, parseInt(costStr, 10))
      ensureDeps(name)
    } else if (directive === 'dep') {
      if (tokens.length < 3) {
        throw new CliError(`error: line ${lineNo}: expected dep <name> <dependency>...`)
      }
      const [, name, ...rest] = tokens
      if (!NAME_RE.test(name)) {
        throw new CliError(`error: line ${lineNo}: invalid task name ${name}`)
      }
      depUses.push(name)
      ensureDeps(name)
      for (const dep of rest) {
        if (!NAME_RE.test(dep)) {
          throw new CliError(`error: line ${lineNo}: invalid task name ${dep}`)
        }
        depUses.push(dep)
        deps.get(name).add(dep)
      }
    } else {
      throw new CliError(`error: line ${lineNo}: unknown directive ${directive}`)
    }
  }

  for (const name of depUses) {
    if (!tasks.has(name)) {
      throw new CliError(`error: unknown task ${name}`)
    }
  }

  return { tasks, deps }
}
"}

