{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-4WTv2n/src/schedule.js","content":"import { CliError } from './errors.js'

/**
 * Finds the first cycle a depth-first search discovers when it starts from
 * each task in ascending name order and walks each task's dependencies in
 * ascending name order. Returns the cycle as an array of names running from
 * the re-entered task back to itself, or `null` when the graph is acyclic.
 */
function findCycle(tasks, deps) {
  const names = [...tasks.keys()].sort()
  const state = new Map()
  const stack = []

  const visit = (name) => {
    state.set(name, 'active')
    stack.push(name)
    const depNames = [...deps.get(name)].sort()
    for (const dep of depNames) {
      const depState = state.get(dep)
      if (depState === 'active') {
        const idx = stack.indexOf(dep)
        return stack.slice(idx).concat(dep)
      }
      if (depState !== 'done') {
        const found = visit(dep)
        if (found) return found
      }
    }
    stack.pop()
    state.set(name, 'done')
    return null
  }

  for (const name of names) {
    if (!state.has(name)) {
      const found = visit(name)
      if (found) return found
    }
  }
  return null
}

/**
 * Validates the graph and derives the values every mode needs: sorted names,
 * each task's dependents, its start/finish/depth under unlimited workers,
 * and its priority (the cost of the longest chain of dependents beginning at
 * it, including its own cost) used to break ties when packing.
 *
 * Throws a `CliError` with exit code 3 when the graph has a cycle.
 */
export function analyzeGraph(tasks, deps) {
  const cycle = findCycle(tasks, deps)
  if (cycle) {
    throw new CliError(`error: cycle: ${cycle.join(' -> ')}`, 3)
  }

  const names = [...tasks.keys()].sort()

  const dependents = new Map(names.map((name) => [name, []]))
  for (const name of names) {
    for (const dep of deps.get(name)) {
      dependents.get(dep).push(name)
    }
  }

  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  const computeTiming = (name) => {
    if (finish.has(name)) return
    let s = 0
    let d = 0
    for (const dep of deps.get(name)) {
      computeTiming(dep)
      s = Math.max(s, finish.get(dep))
      d = Math.max(d, depth.get(dep) + 1)
    }
    start.set(name, s)
    finish.set(name, s + tasks.get(name))
    depth.set(name, d)
  }
  for (const name of names) computeTiming(name)

  const priority = new Map()
  const computePriority = (name) => {
    if (priority.has(name)) return priority.get(name)
    let best = 0
    for (const child of dependents.get(name)) {
      best = Math.max(best, computePriority(child))
    }
    const value = tasks.get(name) + best
    priority.set(name, value)
    return value
  }
  for (const name of names) computePriority(name)

  return { names, deps, start, finish, depth, priority }
}

/** The greatest finish time across all tasks, or 0 when there are none. */
export function totalTime(names, finish) {
  let total = 0
  for (const name of names) total = Math.max(total, finish.get(name))
  return total
}

/**
 * Simulates `workerCount` workers running the graph. At every instant a
 * worker is free, the ready task (all dependencies finished by then) with
 * the greatest priority starts on the lowest-indexed free worker, ties
 * broken by ascending name; time then jumps to the next instant a worker
 * frees up. Returns one run list per worker, each entry `{ name, start,
 * finish }` in the order the worker ran them.
 */
export function packGraph(names, deps, tasks, priority, workerCount) {
  const workers = Array.from({ length: workerCount }, () => ({ freeAt: 0, runs: [] }))
  const finish = new Map()
  const remaining = new Set(names)
  let time = 0

  const isReady = (name) =>
    [...deps.get(name)].every((dep) => finish.has(dep) && finish.get(dep) <= time)

  while (remaining.size > 0) {
    let assignedSomething = true
    while (assignedSomething) {
      assignedSomething = false

      const freeWorkerIndex = workers.findIndex((w) => w.freeAt <= time)
      if (freeWorkerIndex === -1) break

      let best = null
      for (const name of remaining) {
        if (!isReady(name)) continue
        if (
          best === null ||
          priority.get(name) > priority.get(best) ||
          (priority.get(name) === priority.get(best) && name < best)
        ) {
          best = name
        }
      }
      if (best === null) break

      const worker = workers[freeWorkerIndex]
      const taskFinish = time + tasks.get(best)
      worker.runs.push({ name: best, start: time, finish: taskFinish })
      worker.freeAt = taskFinish
      finish.set(best, taskFinish)
      remaining.delete(best)
      assignedSomething = true
    }

    if (remaining.size === 0) break

    const nextTimes = workers.map((w) => w.freeAt).filter((t) => t > time)
    if (nextTimes.length === 0) break
    time = Math.min(...nextTimes)
  }

  return workers
}
"}

