/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { CliError } from './errors.js'
import { parseGraph } from './parse.js'
import { analyzeGraph, totalTime, packGraph } from './schedule.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(argv[1])) {
      throw new CliError('error: workers must be a positive integer')
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError(USAGE)
}

function renderWaves(names, finish, depth) {
  const byDepth = []
  for (const name of names) {
    const d = depth.get(name)
    if (!byDepth[d]) byDepth[d] = []
    byDepth[d].push(name)
  }
  const lines = []
  for (let d = 0; d < byDepth.length; d++) {
    lines.push(`wave ${d}: ${byDepth[d].sort().join(' ')}`)
  }
  lines.push(`total ${totalTime(names, finish)}`)
  return lines.join('\n') + (lines.length ? '\n' : '')
}

function renderExplain(names, start, finish, depth) {
  const lines = names.map(
    (name) => `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`,
  )
  lines.push(`total ${totalTime(names, finish)}`)
  return lines.join('\n') + '\n'
}

function renderPack(workers) {
  const lines = workers.map((worker, i) => {
    const parts = worker.runs.map((run) => ` ${run.name}@${run.start}-${run.finish}`)
    return `worker ${i}:${parts.join('')}`
  })
  let makespan = 0
  for (const worker of workers) {
    for (const run of worker.runs) makespan = Math.max(makespan, run.finish)
  }
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

function main() {
  const { mode, workers } = parseArgs(process.argv.slice(2))
  const input = readFileSync(0, 'utf8')
  const { tasks, deps } = parseGraph(input)
  const { names, start, finish, depth, priority } = analyzeGraph(tasks, deps)

  let output
  if (mode === 'waves') {
    output = renderWaves(names, finish, depth)
  } else if (mode === 'explain') {
    output = renderExplain(names, start, finish, depth)
  } else {
    output = renderPack(packGraph(names, deps, tasks, priority, workers))
  }
  process.stdout.write(output)
}

try {
  main()
} catch (err) {
  if (err instanceof CliError) {
    process.stderr.write(err.message + '\n')
    process.exit(err.code)
  }
  throw err
}
