  const state = new Map()

  for (const start of names) {
    if (state.has(start)) continue

    // Iterative depth-first search: each stack frame remembers which of its
    // dependencies it has already walked, so the walk never recurses and
    // cannot overflow the call stack on a long dependency chain.
    const stack = [{ name: start, idx: 0 }]
    state.set(start, 'active')
    while (stack.length > 0) {
      const frame = stack[stack.length - 1]
      const list = sortedDeps.get(frame.name)
      if (frame.idx < list.length) {
        const dep = list[frame.idx++]
        const depState = state.get(dep)
